#!/bin/bash
python3 - <<'PY'
import csv, json
rows = list(csv.DictReader(open('/app/readings.csv')))
days = [('2026-11-01', '2026-11-01T07:00:00', '2026-11-02T08:00:00'), ('2026-11-02', '2026-11-02T08:00:00', '2026-11-03T08:00:00'), ('2026-11-03', '2026-11-03T08:00:00', '2026-11-04T08:00:00'), ('2026-11-04', '2026-11-04T08:00:00', '2026-11-05T08:00:00'), ('2026-11-05', '2026-11-05T08:00:00', '2026-11-06T08:00:00'), ('2026-11-06', '2026-11-06T08:00:00', '2026-11-07T08:00:00'), ('2026-11-07', '2026-11-07T08:00:00', '2026-11-08T08:00:00'), ('2026-11-08', '2026-11-08T08:00:00', '2026-11-09T08:00:00'), ('2026-11-09', '2026-11-09T08:00:00', '2026-11-10T08:00:00'), ('2026-11-10', '2026-11-10T08:00:00', '2026-11-11T08:00:00'), ('2026-11-11', '2026-11-11T08:00:00', '2026-11-12T08:00:00'), ('2026-11-12', '2026-11-12T08:00:00', '2026-11-13T08:00:00'), ('2026-11-13', '2026-11-13T08:00:00', '2026-11-14T08:00:00'), ('2026-11-14', '2026-11-14T08:00:00', '2026-11-15T08:00:00'), ('2026-11-15', '2026-11-15T08:00:00', '2026-11-16T08:00:00'), ('2026-11-16', '2026-11-16T08:00:00', '2026-11-17T08:00:00'), ('2026-11-17', '2026-11-17T08:00:00', '2026-11-18T08:00:00'), ('2026-11-18', '2026-11-18T08:00:00', '2026-11-19T08:00:00'), ('2026-11-19', '2026-11-19T08:00:00', '2026-11-20T08:00:00'), ('2026-11-20', '2026-11-20T08:00:00', '2026-11-21T08:00:00'), ('2026-11-21', '2026-11-21T08:00:00', '2026-11-22T08:00:00'), ('2026-11-22', '2026-11-22T08:00:00', '2026-11-23T08:00:00'), ('2026-11-23', '2026-11-23T08:00:00', '2026-11-24T08:00:00'), ('2026-11-24', '2026-11-24T08:00:00', '2026-11-25T08:00:00'), ('2026-11-25', '2026-11-25T08:00:00', '2026-11-26T08:00:00'), ('2026-11-26', '2026-11-26T08:00:00', '2026-11-27T08:00:00'), ('2026-11-27', '2026-11-27T08:00:00', '2026-11-28T08:00:00'), ('2026-11-28', '2026-11-28T08:00:00', '2026-11-29T08:00:00'), ('2026-11-29', '2026-11-29T08:00:00', '2026-11-30T08:00:00'), ('2026-11-30', '2026-11-30T08:00:00', '2026-12-01T08:00:00')]
cut = '2026-11-13T18:00:00'
factor = 10
inc, prev = [], None
for r in rows:
    reg = float(r['register_kwh'])
    if prev is not None:
        d = reg - prev
        if d < 0: d += 1000000.0
        if cut and r['ts'] > cut: d *= factor
        inc.append((r['ts'], d))
    prev = reg
daily = {day: sum(d for ts, d in inc if lo < ts <= hi) for day, lo, hi in days}
vals = sorted(daily.values())
median = vals[len(vals) // 2]
low = [d for d, v in daily.items() if v < 0.1 * median]
assert low, 'no implausible day'
json.dump({'status': 'cannot_determine', 'reason': f'consumption on {low[0]} is implausibly low ({daily[low[0]]:.1f} kWh against a typical {median:.0f}), so the meter looks faulty that day and the requested total cannot be relied on', 'flags': ["one day's consumption is implausibly low compared with comparable days; the meter looks faulty that day, so the true consumption is unknown"]}, open('/app/answer.json', 'w'))
PY
